1099	/* "last" is the entry that just exited, or -1 on boot */
1100	
1101	static int launcher_start(int last)
1102	{
1103	  lv_nuttx_dsc_t info;
1104	
1105	  lv_init();
1106	
1107	  lv_nuttx_dsc_init(&info);
1108	  lv_nuttx_init(&info, &g_result);
1109	
1110	  if (g_result.disp == NULL || g_result.indev == NULL)
1111	    {
1112	      fprintf(stderr, "launcher: no display or touchscreen\n");
1113	      return -ENODEV;
1114	    }
1115	
1116	  lv_display_add_event_cb(g_result.disp, launcher_render_cb,
1117	                          LV_EVENT_RENDER_READY, NULL);
1118	  ui_hide_perf();
1119	
1120	  if (g_nentries < 0)
1121	    {
1122	      launcher_load_entries();
1123	    }
1124	
1125	  g_fps = -1;
1126	  launcher_create_about();
1127	  launcher_create_apps();
1128	  launcher_create_home();
1129	  launcher_create_lock();
1130	  lv_screen_load(g_home_scr);
1131	
1132	  launcher_periodic_cb(NULL);
1133	  lv_timer_create(launcher_periodic_cb, 1000, NULL);
1134	  if (g_fifo >= 0)
1135	    {
1136	      lv_timer_create(launcher_fifo_cb, LAUNCHER_FIFO_POLL, NULL);
1137	    }
1138	
1139	  /* Back from an app: to the page it was started from */
1140	
1141	  if (last >= 0)
1142	    {
1143	      lv_obj_add_flag(g_lock, LV_OBJ_FLAG_HIDDEN);
1144	      if (g_from_apps)
1145	        {
1146	          lv_screen_load(g_apps_scr);
1147	        }
1148	      else
1149	        {
1150	          launcher_home_intro();
1151	        }
1152	    }
1153	
1154	  return 0;
1155	}
