1163	/****************************************************************************
1164	 * Public Functions
1165	 ****************************************************************************/
1166	
1167	int main(int argc, FAR char *argv[])
1168	{
1169	  FAR const struct builtin_s *app;
1170	  FAR char *args[2];
1171	  FAR char **argp;
1172	  uint32_t idle;
1173	  int last = -1;
1174	  pid_t pid;
1175	
1176	  UNUSED(argc);
1177	  UNUSED(argv);
1178	
1179	  if (lv_is_initialized())
1180	    {
1181	      fprintf(stderr, "launcher: LVGL is busy\n");
1182	      return 1;
1183	    }
1184	
1185	#ifdef CONFIG_PIPES
1186	  mkfifo(LAUNCHER_FIFO, 0666);
1187	  g_fifo = open(LAUNCHER_FIFO, O_RDONLY | O_NONBLOCK);
1188	#endif
1189	
1190	  while (launcher_start(last) == 0)
1191	    {
1192	      g_launch = -1;
1193	      while (g_launch < 0)
1194	        {
1195	          idle = lv_timer_handler();
1196	          usleep(MAX(idle, 1) * 1000);
1197	        }
1198	
1199	      /* Show the pressed tile while the app starts */
1200	
1201	      lv_refr_now(NULL);
1202	      launcher_stop();
1203	
1204	      last = g_launch;
1205	      app = builtin_for_index(g_entries[last].index);
1206	      args[0] = (FAR char *)g_entries[last].app.arg;
1207	      args[1] = NULL;
1208	      argp = g_fifo_args[0] != NULL ? g_fifo_args :
1209	             args[0] != NULL ? args : NULL;
1210	      pid = task_create(app->name, app->priority, app->stacksize, app->main,
1211	                        argp);
1212	      g_fifo_args[0] = NULL;
1213	      if (pid < 0)
1214	        {
1215	          fprintf(stderr, "launcher: start %s failed: %d\n", app->name,
1216	                  errno);
1217	        }
1218	      else
1219	        {
1220	          waitpid(pid, NULL, 0);
1221	        }
1222	    }
1223	
1224	  launcher_stop();
1225	  return 1;
1226	}
