1068	
1069	  g_fps = lv_display_get_inactive_time(NULL) > LAUNCHER_IDLE_TIME &&
1070	          g_frames <= LAUNCHER_IDLE_FRAMES ? -1 : (int)g_frames;
1071	  g_frames = 0;
1072	
1073	  snprintf(text, sizeof(text), "%02u", sec / 3600 % 100);
1074	  ui_num_set(g_lock_hour, text, anim);
1075	  snprintf(text, sizeof(text), "%02u", sec / 60 % 60);
1076	  ui_num_set(g_lock_min, text, anim);
1077	  snprintf(text, sizeof(text), "%02u", sec % 60);
1078	  ui_num_set(g_lock_sec, text, anim);
1079	  ui_num_set(g_home_sec, text, anim);
1080	  snprintf(text, sizeof(text), "%02u:%02u", sec / 3600 % 100,
1081	           sec / 60 % 60);
1082	  ui_num_set(g_home_clock, text, anim);
1083	
1084	  snprintf(text, sizeof(text), "%uM", mi.fordblks >> 20);
1085	  ui_num_set(g_home_heap, text, anim);
1086	  lv_label_set_text_fmt(g_home_uptime, "%uh %um", sec / 3600,
1087	                        sec / 60 % 60);
1088	  lv_label_set_text_fmt(g_about_heap, "Heap %uKB free of %uKB",
1089	                        mi.fordblks >> 10, mi.arena >> 10);
1090	  lv_obj_set_width(g_about_bar, launcher_heap_used(&mi));
1091	
1092	  launcher_fps_text(text, sizeof(text), " FPS");
1093	  lv_label_set_text(g_top_fps, text);
1094	  launcher_fps_text(text, sizeof(text), "");
1095	  ui_num_set(g_home_fps, text, anim);
1096	  ui_num_set(g_about_fps, text, anim);
1097	}
