/* The address of LAUNCHER_NETDEV while it has a link.  The labels change
 * only with the state, so an idle home screen stays idle.
 */

static void launcher_net_update(void)
{
  struct in_addr addr;
  uint8_t flags = 0;
  int64_t shown = 0;

  if (netlib_getifstatus(LAUNCHER_NETDEV, &flags) == 0 &&
      (flags & IFF_RUNNING) != 0 &&
      netlib_get_ipv4addr(LAUNCHER_NETDEV, &addr) == 0)
    {
      shown = (int64_t)addr.s_addr + 1;
    }

  if (shown == g_net_shown)
    {
      return;
    }

  g_net_shown = shown;
  lv_label_set_text(g_home_net, shown ? "ETHERNET  /  LINK" :
                                        "ETHERNET  /  NO LINK");
  lv_obj_set_style_text_color(g_home_net,
                              lv_color_hex(shown ? UI_BLUE : UI_DIM), 0);
  lv_label_set_text(g_home_strip, shown ? inet_ntoa(addr) : "OFFLINE");
  lv_obj_set_style_text_color(g_home_strip,
                              lv_color_hex(shown ? UI_INK : UI_MUTED), 0);
}
#endif

